import{_ as l,C as p,o,c as h,j as n,a as t,b as a,w as s,E as r,a3 as c,a2 as d}from"./chunks/framework.CZqXuAiL.js";const E=JSON.parse('{"title":"Architecture Overview","description":"How Protection Plus is built — the single shared system snapshot, /proc and network-namespace introspection, the detector pipeline, engine, enforcement backends, intel and on-access subsystems, self-protection and the resource-safety model.","frontmatter":{"title":"Architecture Overview","description":"How Protection Plus is built — the single shared system snapshot, /proc and network-namespace introspection, the detector pipeline, engine, enforcement backends, intel and on-access subsystems, self-protection and the resource-safety model."},"headers":[],"relativePath":"protection/architecture/overview.md","filePath":"protection/architecture/overview.md","lastUpdated":null}'),u={name:"protection/architecture/overview.md"};function g(m,e,k,f,y,b){const i=p("Mermaid");return o(),h("div",null,[e[3]||(e[3]=n("h1",{id:"architecture-overview",tabindex:"-1"},[t("Architecture Overview "),n("a",{class:"header-anchor",href:"#architecture-overview","aria-label":'Permalink to "Architecture Overview"'},"​")],-1)),e[4]||(e[4]=n("p",null,[t("Protection Plus is a single static Go binary (zero cgo) that gathers system state from "),n("code",null,"/proc"),t(" and the Docker socket, runs it through independent detectors, and feeds the resulting events into an engine that alerts and enforces. This page walks through how the pieces fit together in v1.0.0.")],-1)),(o(),a(c,null,{default:s(()=>[r(i,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Capture%0A%20%20%20%20%20%20%20%20PROC%5B%22%2Fproc%20(host%20%2B%20every%20container%20netns)%22%5D%20--%3E%20SNAP%5B%22system.Gather()%22%5D%0A%20%20%20%20%20%20%20%20DOCK%5BDocker%20socket%5D%20--%3E%20SNAP%0A%20%20%20%20%20%20%20%20SNAP%20--%3E%20ONE%5B%22One%20Snapshot%20per%20tick%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Detectors%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20M%5Bminer%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20P%5Bportscan%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20D%5Bddos%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20Z%5Bzipbomb%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20E%5Bexploit%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20AB%5Babuse%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20Y%5Byara%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20TV%5Btrivy%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20F%5Bfim%5D%0A%20%20%20%20%20%20%20%20ONE%20--%3E%20OA%5Bonaccess%5D%0A%20%20%20%20end%0A%0A%20%20%20%20M%20--%3E%20ENG%5BEngine%5D%0A%20%20%20%20P%20--%3E%20ENG%0A%20%20%20%20D%20--%3E%20ENG%0A%20%20%20%20Z%20--%3E%20ENG%0A%20%20%20%20E%20--%3E%20ENG%0A%20%20%20%20AB%20--%3E%20ENG%0A%20%20%20%20Y%20--%3E%20ENG%0A%20%20%20%20TV%20--%3E%20ENG%0A%20%20%20%20F%20--%3E%20ENG%0A%20%20%20%20OA%20--%3E%20ENG%0A%0A%20%20%20%20subgraph%20Engine%0A%20%20%20%20%20%20%20%20ENG%20--%3E%20SCOPE%5Bwhitelist%20%2B%20mode%20scope%5D%0A%20%20%20%20%20%20%20%20SCOPE%20--%3E%20DEDUP%5B%22Key()%20%2B%20cooldown%20dedup%22%5D%0A%20%20%20%20%20%20%20%20DEDUP%20--%3E%20RULES%5Brule%20match%5D%0A%20%20%20%20end%0A%0A%20%20%20%20RULES%20--%3E%20ALERTS%5BAlert%20fan-out%5D%0A%20%20%20%20RULES%20--%3E%20ACTIONS%5BEnforcement%5D%0A%20%20%20%20ALERTS%20--%3E%20CH%5BDiscord%20%C2%B7%20SMTP%20%C2%B7%20Webhook%5D%0A%20%20%20%20ACTIONS%20--%3E%20EN%5Bneutralize%20%C2%B7%20suspend_server%20%C2%B7%20quarantine_file%20%C2%B7%20kill_process%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=d('<hr><h2 id="the-single-snapshot-model" tabindex="-1">The single-snapshot model <a class="header-anchor" href="#the-single-snapshot-model" aria-label="Permalink to &quot;The single-snapshot model&quot;">​</a></h2><p>The most important design choice: <strong>one capture per tick, shared by every detector.</strong></p><p>On each <code>scan_interval</code>, the engine calls <code>system.Gather()</code> exactly once to build a <code>Snapshot</code> containing:</p><ul><li><strong>Processes</strong> — full process table with CPU jiffies, disk read/write byte counters, UID, PGRP and container attribution (see below).</li><li><strong>Connections</strong> — host <em>and</em> every container network namespace, TCP and UDP, with owning PIDs resolved.</li><li><strong>CPU totals</strong> (<code>CPUTotal</code>) and <strong>CPU count</strong> (<code>NumCPU</code>) for percentage maths.</li><li>A pre-built <code>byPID</code> index so detectors do O(1) process lookups instead of rescanning.</li></ul><p>Every detector reads from this one snapshot instead of independently walking <code>/proc</code>. That cuts the most expensive part of a scan — the <code>/proc</code> and socket-table traversals — from roughly four walks per tick to one, a <strong>~4x reduction in syscall cost</strong> (the figure is documented in the <code>Snapshot</code> source itself).</p><hr><h2 id="process-introspection-from-proc" tabindex="-1">Process introspection from /proc <a class="header-anchor" href="#process-introspection-from-proc" aria-label="Permalink to &quot;Process introspection from /proc&quot;">​</a></h2><p>Everything Protection Plus knows about processes comes straight from <code>/proc</code>, in pure Go — no cgo, no external tools. For each PID it reads:</p><ul><li><code>stat</code> — comm, state, <strong>PGRP</strong> (process group), user/kernel jiffies, start time. PGRP matters because detectors aggregate by process group for <strong>pipeline-aware rates</strong>: <code>tar czf - dir | gzip &gt; out.tgz</code> is measured as one workload, not two innocent-looking halves.</li><li><code>cmdline</code> — the full command line (NUL-joined into spaces).</li><li><code>exe</code> — the resolved binary path (a symlink read).</li><li><code>status</code> — the real UID.</li><li><code>cgroup</code> — parsed for a 64-hex container id; works for cgroup v1 and v2 across docker/containerd/k8s, so every process is attributed to its container for free.</li><li><code>io</code> — cumulative <code>read_bytes</code>/<code>write_bytes</code> counters (requires root or <code>CAP_SYS_PTRACE</code>; degrades to zeros otherwise).</li></ul><p>CPU percentages are derived from jiffy deltas between ticks against <code>/proc/stat</code> totals. <code>USER_HZ</code> is hardcoded to 100 (effectively always true on Linux) to avoid a cgo <code>sysconf</code> call. Processes that exit mid-read are skipped quietly — a partially readable <code>/proc</code> is a normal Tuesday, not an error.</p><hr><h2 id="container-network-namespace-visibility" tabindex="-1">Container network-namespace visibility <a class="header-anchor" href="#container-network-namespace-visibility" aria-label="Permalink to &quot;Container network-namespace visibility&quot;">​</a></h2><p>Docker/containerd give each container its <strong>own network namespace</strong>, so container sockets never appear in the host&#39;s <code>/proc/net/tcp</code>. Protection Plus handles this explicitly:</p>',14)),(o(),a(c,null,{default:s(()=>[r(i,{id:"mermaid-91",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20PROCS%5BAll%20processes%5D%20--%3E%20GRP%7BGroup%20by%20netns%20inode%3Cbr%2F%3E%2Fproc%2F%26lt%3Bpid%26gt%3B%2Fns%2Fnet%7D%0A%20%20%20%20GRP%20--%3E%20HOST%5BHost%20namespace%5D%0A%20%20%20%20GRP%20--%3E%20C1%5BContainer%20A%20netns%5D%0A%20%20%20%20GRP%20--%3E%20C2%5BContainer%20B%20netns%5D%0A%20%20%20%20HOST%20--%3E%20RH%5B%22read%20%2Fproc%2Fnet%2Ftcp%7B%2C6%7D%20%2B%20udp%7B%2C6%7D%3Cbr%2F%3Efd-scan%20for%20PIDs%22%5D%0A%20%20%20%20C1%20--%3E%20R1%5B%22read%20%2Fproc%2F%26lt%3Brep%26gt%3B%2Fnet%2Ftcp%7B%2C6%7D%20%2B%20udp%7B%2C6%7D%3Cbr%2F%3Escoped%20fd-scan%22%5D%0A%20%20%20%20C2%20--%3E%20R2%5B%22read%20%2Fproc%2F%26lt%3Brep%26gt%3B%2Fnet%2Ftcp%7B%2C6%7D%20%2B%20udp%7B%2C6%7D%3Cbr%2F%3Escoped%20fd-scan%22%5D%0A%20%20%20%20RH%20--%3E%20CONNS%5BUnified%20connection%20list%5D%0A%20%20%20%20R1%20--%3E%20CONNS%0A%20%20%20%20R2%20--%3E%20CONNS%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=d(`<ul><li>Processes are bucketed by their network-namespace inode (read from <code>/proc/&lt;pid&gt;/ns/net</code>).</li><li>The host namespace is read from <code>/proc/net/tcp{,6}</code> <strong>and</strong> <code>/proc/net/udp{,6}</code> — UDP support means amplification-style abuse and QUIC traffic are visible too.</li><li>Each <strong>container</strong> namespace is read through one of its own processes (<code>/proc/&lt;pid&gt;/net/tcp</code> and the UDP equivalents), where <code>&lt;pid&gt;</code> is the lowest PID in that namespace&#39;s bucket.</li><li>Container connections get attribution for free: the socket→PID mapping is scoped to just that container&#39;s (few) processes, so there&#39;s <strong>no host-wide fd walk</strong> for container traffic, and any unresolved socket falls back to the container&#39;s main process.</li><li>Host-network-mode containers are still attributed, via the process table&#39;s container ids.</li></ul><p>The result: a miner phoning a pool or a scan launched from inside a container is fully visible and correctly attributed. Inspect it live with <a href="./../user-guide/cli#protection-debug-conns"><code>protection debug-conns</code></a>.</p><hr><h2 id="socket-→-pid-resolution" tabindex="-1">Socket → PID resolution <a class="header-anchor" href="#socket-→-pid-resolution" aria-label="Permalink to &quot;Socket → PID resolution&quot;">​</a></h2><p>Mapping a connection to its owning process means matching each socket inode against a <code>socket:[inode]</code> symlink in some <code>/proc/&lt;pid&gt;/fd</code> directory — one <code>readlink</code> per fd, and busy hosts can have hundreds of thousands of fds. Protection Plus keeps this bounded:</p><ul><li><strong>Worker pool</strong> — the fd walk fans out across <code>NumCPU × 4</code> workers (minimum 4, capped at 64).</li><li><strong>Chunked within processes</strong> — each process&#39;s fd list is split into 2048-entry chunks, so a single fd-heavy process (a leak, or an abuser deliberately holding many sockets) is spread across all workers instead of pinning one.</li><li><strong>1.5 s time budget</strong> — <code>pidResolveBudget</code> caps total resolution time per scan. On a healthy node this never triggers (resolution finishes in milliseconds); if it does trip, Protection Plus degrades gracefully: unresolved connections simply have <code>PID == 0</code>, are skipped by pid-level checks, and container-level checks are unaffected.</li></ul><hr><h2 id="the-detector-interface" tabindex="-1">The detector interface <a class="header-anchor" href="#the-detector-interface" aria-label="Permalink to &quot;The detector interface&quot;">​</a></h2><p>Every detector is an independent unit behind one tiny interface (<code>internal/detectors/detector.go</code>):</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Detector</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">snap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">system</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Snapshot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ([]</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>Run</code> is called once per tick with the shared snapshot and must return within roughly one interval. A detector emits <code>core.Event</code> values — severity, category, title, description, target (pid/container/path) and free-form evidence — and the engine does the rest.</p><p><strong>Adding a new detector</strong> is two steps:</p><ol><li>Implement <code>Name()</code> + <code>Run(ctx, *system.Snapshot)</code> in <code>internal/detectors/</code>.</li><li>Register it in <code>buildDetectors()</code> in <code>cmd/protection/main.go</code> (gated on its config section).</li></ol><p>Scoping, dedup, rule matching, alerting, batching, rate limiting and enforcement all work unchanged — the new detector just starts emitting events. Detectors that need deltas (CPU%, disk-write rate) keep small per-PID state between ticks; a shared <code>containerResolver</code> caches container-id → name/server-uuid lookups for 30 s so every detector can annotate events cheaply.</p><hr><h2 id="the-engine" tabindex="-1">The engine <a class="header-anchor" href="#the-engine" aria-label="Permalink to &quot;The engine&quot;">​</a></h2><p>The engine orchestrates everything after detection:</p>`,17)),(o(),a(c,null,{default:s(()=>[r(i,{id:"mermaid-182",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20T%20as%20Ticker%20(scan_interval)%0A%20%20%20%20participant%20G%20as%20system.Gather%0A%20%20%20%20participant%20D%20as%20Detectors%0A%20%20%20%20participant%20E%20as%20Engine%0A%20%20%20%20participant%20A%20as%20Alerts%20%2B%20Actions%0A%0A%20%20%20%20T-%3E%3EG%3A%20one%20Snapshot%0A%20%20%20%20G-%3E%3ED%3A%20shared%20snapshot%0A%20%20%20%20D-%3E%3EE%3A%20%5B%5DEvent%20(per-detector%20timeout)%0A%20%20%20%20E-%3E%3EE%3A%20whitelist%20%2B%20mode%20scope%0A%20%20%20%20E-%3E%3EE%3A%20Key()%20cooldown%20dedup%0A%20%20%20%20E-%3E%3EE%3A%20match%20rules%20(union%20of%20actions)%0A%20%20%20%20E-%3E%3EA%3A%20batch%20%2F%20rate-limit%2C%20fan%20out%0A"})]),fallback:s(()=>[...e[2]||(e[2]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=d(`<ol><li><strong>Whitelist &amp; scope</strong> — events matching a whitelisted path or container are dropped first; then <code>general.mode</code> (<code>server</code>, <code>docker</code>, <code>both</code>) decides whether container-related and host events are in scope at all.</li><li><strong>Cooldown dedup</strong> — each event computes a stable <code>Key()</code> (<code>category|detector|target</code>, where target is the container id, path, or <code>pid:N</code>). Repeat findings for the same key inside <code>general.cooldown</code> are suppressed, and the key map is garbage-collected opportunistically.</li><li><strong>Rule match</strong> — every rule whose category list (<code>*</code> or explicit) and <code>min_severity</code> match contributes its actions; the engine takes the <strong>union</strong>.</li><li><strong>Dispatch</strong> — enforcement actions run sequentially (respecting global <code>dry_run</code>); alerts fan out concurrently.</li></ol><p>Alert delivery has three layers of control:</p><ul><li><strong>Per-channel severity gates</strong> — each channel has its own <code>min_severity</code>; a channel only receives events at or above it. Each send runs in its own goroutine with a 12 s timeout, so a slow webhook never blocks detection.</li><li><strong>Optional batching</strong> — when <code>alerts.batch</code> is enabled, alerts flow individually until a threshold of events arrives inside a window; Protection Plus then switches to digest mode and delivers one summarised &quot;N security events (batched)&quot; alert per burst instead of a flood.</li><li><strong>Optional rate limit</strong> — <code>limits.max_alerts_per_minute</code> caps total dispatches per minute (disabled by default); when the cap trips, one warning is logged per minute and the rest are dropped.</li></ul><p>Detectors themselves get an optional <strong>per-detector timeout</strong> (<code>limits.detector_timeout</code>): a detector that overruns its context is aborted with a warning and the tick continues without it.</p><hr><h2 id="enforcement-backends" tabindex="-1">Enforcement backends <a class="header-anchor" href="#enforcement-backends" aria-label="Permalink to &quot;Enforcement backends&quot;">​</a></h2><p>Actions live behind a <code>Registry</code> keyed by the names rules reference; every action honours the global dry-run switch. The backends:</p><ul><li><strong>Docker</strong> (<code>kill_container</code>, <code>stop_container</code>) — a deliberately tiny Docker Engine API client speaking HTTP over the unix socket (<code>internal/docker</code>). The official SDK and its dependency tree are avoided; only a handful of endpoints are needed, with a 5 s dial and 15 s request timeout.</li><li><strong>Pterodactyl</strong> (<code>suspend_server</code>) — resolves the panel&#39;s internal server id from the event&#39;s server uuid/identifier (derived from Wings container labels/names) via the application API, then suspends. Skips quietly on events with no associated server, so it can sit harmlessly in a shared rule.</li><li><strong>File quarantine</strong> (<code>quarantine_file</code>) — moves the offending file into a locked-down quarantine directory (<code>0700</code>) instead of deleting it, preserving evidence. Uses <code>rename</code> with a copy-then-remove fallback across filesystems, then <code>chmod 000</code> so the payload can&#39;t be executed. (<code>delete_file</code> exists for when you really mean it.)</li><li><strong>Smart neutralize</strong> (<code>neutralize</code>) — the default-rule action: containerised threat with Docker available → kill the container; otherwise → <code>SIGKILL</code> the process. One policy line works on Pterodactyl/Docker nodes and plain VPS hosts alike.</li></ul><hr><h2 id="the-intel-subsystem" tabindex="-1">The intel subsystem <a class="header-anchor" href="#the-intel-subsystem" aria-label="Permalink to &quot;The intel subsystem&quot;">​</a></h2><p><code>internal/intel</code> keeps the threat intelligence fresh: the YARA rule set and the SHA-256 malware hash blocklist (MalwareBazaar export).</p><ul><li><strong>Atomic downloads</strong> — every write is temp-file-then-<code>rename</code>, so readers never see a partial file. Temp files live next to the destination (same filesystem for the rename, and inside the daemon&#39;s writable state dir, since systemd sandboxes make <code>/tmp</code> read-only for the service).</li><li><strong>Streaming hashlist parse</strong> — the export may arrive as raw text or a zip; either way it&#39;s streamed to disk and parsed line-by-line, so even the multi-hundred-MB &quot;full&quot; export never sits in memory at once. Lines are lowercased, validated as SHA-256 hex, deduplicated and stored one hash per line. Zip payloads are extracted by streaming the first regular file to a temp file that deletes itself on close.</li><li><strong>Independent failure domains</strong> — rules and hashlist update separately; one source failing never blocks the other, and partial success is reported as such.</li><li>The in-memory <code>HashList</code> is an RWMutex-guarded set with case-insensitive lookups, loaded from the downloaded blocklist plus an optional operator-supplied custom list.</li></ul><hr><h2 id="the-on-access-subsystem" tabindex="-1">The on-access subsystem <a class="header-anchor" href="#the-on-access-subsystem" aria-label="Permalink to &quot;The on-access subsystem&quot;">​</a></h2><p>Periodic sweeps are the backstop; <strong>on-access scanning</strong> is the fast path that catches a malicious upload the moment it lands. <code>internal/detectors/onaccess.go</code> combines fsnotify with a bounded worker pool:</p><ul><li>A single <strong>fsnotify watcher</strong> covers every configured upload path recursively (new directories are added to the watch set as they appear). The watcher starts lazily on the first <code>Run</code> call so the engine can construct all detectors up front without paying for inotify watches it may never use.</li><li>Writes are <strong>debounced</strong> per path (default 500 ms settle): editors and downloaders write in bursts, and scanning a half-written file wastes I/O and can misfire.</li><li>Settled files go through a <strong>worker pool capped at 2 concurrent scans</strong> — a SHA-256 blocklist lookup and, if the <code>yara</code> binary is in PATH, a YARA sweep against the intel-maintained rules.</li><li>Hard bounds everywhere: blocklist hashing skips files over 512 MiB, YARA skips files over 64 MiB with a 30 s per-invocation timeout, and the pending-event queue is capped at 1000 (oldest dropped, with a warning) so a write storm can&#39;t grow memory without bound.</li><li>Scanning happens in background workers decoupled from the engine tick; <code>Run</code> simply drains whatever the workers found since the last call. Watcher errors (queue overflows and the like) are skipped silently — the periodic sweeps remain the backstop.</li></ul><hr><h2 id="self-protection" tabindex="-1">Self-protection <a class="header-anchor" href="#self-protection" aria-label="Permalink to &quot;Self-protection&quot;">​</a></h2><p>A security daemon is itself a target, so Protection Plus watches its own back:</p><ul><li><strong>FIM</strong> — the <code>fim</code> detector watches operator-listed files (the daemon&#39;s own binary, config, unit files, …). The first sighting records a SHA-256 baseline (streamed, so multi-gigabyte files never load into memory); any later content change raises a high-severity event and becomes the new baseline, so each change alerts exactly once. Hashing honours its own configured interval rather than running every tick.</li><li><strong>systemd watchdog</strong> — the engine reports <code>READY=1</code> at startup, pets <code>WATCHDOG=1</code> after every scan, and sends <code>STOPPING=1</code> on shutdown. If the detection loop hangs past <code>WatchdogSec</code> (60 s in the shipped unit), systemd kills and restarts the service. The <code>sd_notify</code> protocol is implemented in <strong>pure Go</strong> (<code>internal/system/sdnotify.go</code>) — a unixgram datagram to <code>$NOTIFY_SOCKET</code>, abstract-socket <code>@</code> prefix handled — with no cgo and no libsystemd dependency. It&#39;s a no-op when not running under systemd.</li><li><strong>Unit hardening</strong> — the shipped unit runs with <code>ProtectSystem=strict</code>, <code>ProtectHome=read-only</code>, and only three ambient capabilities (<code>CAP_SYS_PTRACE</code>, <code>CAP_KILL</code>, <code>CAP_DAC_READ_SEARCH</code>). Writes are limited to <code>ReadWritePaths=/var/lib/protection /var/log -/var/lib/pterodactyl/volumes</code> — the <code>-</code> prefix means the Pterodactyl path is skipped when absent, so the same unit starts cleanly on non-Pterodactyl hosts.</li></ul><hr><h2 id="resource-safety-design" tabindex="-1">Resource-safety design <a class="header-anchor" href="#resource-safety-design" aria-label="Permalink to &quot;Resource-safety design&quot;">​</a></h2><p>The watchdog must never become the problem it&#39;s watching for. Resource safety is layered:</p><ul><li><strong>Config <code>limits</code> section</strong> — everything is opt-in: <code>detector_timeout</code> caps a single detector per tick, <code>max_alerts_per_minute</code> caps alert fan-out. Neither is enabled by default.</li><li><strong>Worker pools</strong> — socket→PID resolution uses a capped pool (max 64 workers); on-access scanning caps concurrent file scans at 2; alert sends are goroutines with individual timeouts.</li><li><strong>Time budgets</strong> — 1.5 s for PID resolution, 30 s per YARA invocation, 12 s per alert send, 5 s/15 s on the Docker client, 5 minutes on intel downloads. Nothing in the hot path can block forever.</li><li><strong>Size caps</strong> — 512 MiB for on-access hashing, 64 MiB for on-access YARA, bounded event queues and digest text.</li><li><strong>mtime caches</strong> — sweep detectors (zipbomb, exploit) keep a directory-mtime cache and skip walking directories that haven&#39;t changed since the last pass (best-effort: some filesystems don&#39;t update directory mtime on every change).</li><li><strong>systemd guardrails</strong> — the unit caps the daemon at <code>MemoryMax=256M</code> and <code>CPUQuota=50%</code>, so even a pathological host can&#39;t let Protection Plus starve the workloads it protects.</li></ul><hr><h2 id="source-layout" tabindex="-1">Source layout <a class="header-anchor" href="#source-layout" aria-label="Permalink to &quot;Source layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmd/protection        CLI entrypoint, embedded starter config, detector wiring</span></span>
<span class="line"><span>internal/core         Event, Severity, Category (shared leaf package)</span></span>
<span class="line"><span>internal/config       YAML config + defaults + validation</span></span>
<span class="line"><span>internal/system       /proc + netns introspection, sd_notify (pure Go)</span></span>
<span class="line"><span>internal/docker       tiny Docker Engine API client over the unix socket</span></span>
<span class="line"><span>internal/intel        threat-intel downloads + hash blocklist</span></span>
<span class="line"><span>internal/detectors    miner, portscan, ddos, zipbomb, exploit, abuse,</span></span>
<span class="line"><span>                      yara, trivy, fim, onaccess</span></span>
<span class="line"><span>internal/alerts       discord, smtp, webhook</span></span>
<span class="line"><span>internal/actions      docker, file, pterodactyl, process, neutralize</span></span>
<span class="line"><span>internal/engine       scheduler, scope, dedup, rule matching, dispatch,</span></span>
<span class="line"><span>                      batching, rate limiting</span></span>
<span class="line"><span>packaging             systemd unit (hardened, watchdog-enabled)</span></span></code></pre></div><hr><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><ul><li><strong>Host-side, agentless</strong> — tenants can&#39;t see or evade it.</li><li><strong>Pure Go, single static binary</strong> — drop it anywhere, no runtime deps (even <code>sd_notify</code> is hand-rolled).</li><li><strong>Safe by default</strong> — dry-run first; destructive actions and all resource limits are opt-in.</li><li><strong>One snapshot, many detectors</strong> — cheap and consistent.</li><li><strong>Bounded everything</strong> — worker pools, time budgets, size caps and mtime caches keep the daemon cheap on pathological hosts.</li><li><strong>Graceful degradation</strong> — missing root, missing Docker, a missing <code>yara</code> binary or a socket-leaking neighbour reduces capability rather than breaking the loop.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./../user-guide/detection">How Detection Works →</a></strong> — per-detector logic.</li><li><strong><a href="./../user-guide/actions-rules">Actions &amp; Rules →</a></strong> — how findings become enforcement.</li><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — tune the model above.</li></ul>`,32))])}const w=l(u,[["render",g]]);export{E as __pageData,w as default};
